import random
RCn=random.Random(77)
def _o(a,pool):
    c=[x for x in dict.fromkeys(pool) if x!=a and len(x.split())==len(a.split())]; RCn.shuffle(c); return [a]+c[:3]
def geo_qs(kinds=("cap","rev","cur","cont")):
    caps=[c[1] for c in CT]; names=[c[0] for c in CT]; curs=[c[3] for c in CT]
    out=[]
    for n,cap,cont,cur in CT:
        if "cap" in kinds: out.append((f"ما عاصمة {n}؟",_o(cap,caps)))
        if "rev" in kinds: out.append((f"مدينة {cap} هي عاصمة أي دولة؟",_o(n,names)))
        if "cur" in kinds:
            others=[x for x in curs if x!=cur]
            out.append((f"ما اسم عملة {n}؟",_o(cur,others)))
        if "cont" in kinds:
            pool=["آسيا","أفريقيا","أوروبا","أوقيانوسيا"] if len(cont.split())==1 else ["أمريكا الشمالية","أمريكا الجنوبية","أمريكا الوسطى","القارة القطبية"]
            out.append((f"في أي قارة تقع {n}؟",_o(cont,pool)))
    return out
